  isSessionExpired: false,
  isInitialized: false,

  /**
   * 앱 시작 시 SecureStore에서 인증 데이터 복원
   * - 토큰 존재 여부만 확인 (만료 무시 - 오프라인 지원)
   * - user 정보도 함께 복원 (오프라인에서 프로필 표시)
   */
  init: async () => {
