import React from 'react';
import { View, Text } from 'react-native';
import { Pressable } from '@repo/ui';
import { Database, Wifi, WifiOff, RotateCcw, RefreshCw, Upload } from 'lucide-react-native';
import {
  useNetworkCheck,
  useNetworkControl,
  useDisplayNetworkStatus,
  useRealNetworkStatus,
} from '@/shared/store/network';

const NETWORK_STATUS_DISPLAY = {
  online: {
    Icon: Wifi,
    color: '#228B22',
    textClassName: 'text-primary',
    label: '🟢 온라인',
  },
  offline: {
    Icon: WifiOff,
    color: '#BF4040',
    textClassName: 'text-destructive',
    label: '🔴 오프라인',
  },
  unknown: {
    Icon: Wifi,
    color: '#666',
    textClassName: 'text-muted-foreground',
    label: '⚪ 미확정',
  },
};

interface DashboardViewProps {
  stats: { pending: number; inProgress: number; failed: number; total: number } | null;
  counts: {
    trips: number;
    schedules: number;
    expenses: number;
    activations: number;
    offlineCities: number;
  };
  onRefresh: () => void;
  onManualSync: () => void;
}

export function DashboardView({ stats, counts, onRefresh, onManualSync }: DashboardViewProps) {
  const { overrideStatus, setOverrideOnline, setOverrideOffline, setOverrideUnknown, clearOverride } =
    useNetworkControl();
  const realNetworkStatus = useRealNetworkStatus();
  const displayStatus = useDisplayNetworkStatus();
  const { checkStatus, isRefreshing, refresh } = useNetworkCheck();

  const { Icon: StatusIcon, color, textClassName, label } = NETWORK_STATUS_DISPLAY[displayStatus];

  return (
    <View className='gap-md'>
      {/* Network Status Card */}
      <View className='rounded-lg bg-card p-md border border-card-border'>
        <View className='flex-row items-center gap-xs mb-sm'>
          <StatusIcon size={20} color={color} />
          <Text className='text-title-medium text-foreground'>네트워크 상태</Text>
        </View>
        <View className='gap-2xs mb-sm'>
          <Text className='text-body text-foreground'>
            현재 상태: <Text className={`${textClassName} font-semibold`}>{label}</Text>
          </Text>
          <Text className='text-label text-muted-foreground'>실제 네트워크: {realNetworkStatus}</Text>
          {overrideStatus && <Text className='text-label text-muted-foreground'>⚠️ 강제 설정: {overrideStatus}</Text>}
          {realNetworkStatus === 'unknown' && (
            <Text className='text-label text-muted-foreground'>
              {checkStatus === 'unavailable' ? '인터넷 연결을 확인할 수 없어요' : '인터넷 연결 확인 중'}
            </Text>
          )}
        </View>
        <View className='flex-row gap-xs'>
          <Pressable
            variant='outline'
            className='flex-1 flex-row items-center justify-center gap-xs py-xs rounded-lg border border-primary'
            onPress={setOverrideOnline}
          >
            <Wifi size={14} color='#228B22' />
            <Text className='text-label text-primary'>온라인</Text>
          </Pressable>
          <Pressable
            variant='outline'
            className='flex-1 flex-row items-center justify-center gap-xs py-xs rounded-lg border border-destructive'
            onPress={setOverrideOffline}
          >
            <WifiOff size={14} color='#BF4040' />
            <Text className='text-label text-destructive'>오프라인</Text>
          </Pressable>
          <Pressable variant='outline' className='flex-1 py-xs' onPress={setOverrideUnknown}>
            <Text className='text-label text-muted-foreground'>미확정</Text>
          </Pressable>
          <Pressable
            variant='outline'
            className='flex-1 flex-row items-center justify-center gap-xs py-xs rounded-lg border border-card-border'
            onPress={clearOverride}
          >
            <RotateCcw size={14} color='#666' />
            <Text className='text-label text-muted-foreground'>실제</Text>
          </Pressable>
        </View>
        <Pressable variant='outline' className='mt-sm' onPress={refresh} disabled={isRefreshing}>
          {isRefreshing ? '재확인 중...' : '실제 연결 재확인'}
        </Pressable>
      </View>

      {/* DB Stats Card */}
      <View className='rounded-lg bg-card p-md border border-card-border'>
        <View className='flex-row items-center gap-xs mb-sm'>
          <Database size={20} color='#228B22' />
          <Text className='text-title-medium text-foreground'>DB 통계</Text>
        </View>
        <View className='gap-2xs'>
          <Text className='text-body text-foreground'>여행: {counts.trips}개</Text>
          <Text className='text-body text-foreground'>일정: {counts.schedules}개</Text>
          <Text className='text-body text-foreground'>경비: {counts.expenses}개</Text>
          <Text className='text-body text-foreground'>활성화된 여행: {counts.activations}개</Text>
          <Text className='text-body text-foreground'>오프라인 지도: {counts.offlineCities}개</Text>
          {stats && (
            <>
              <Text className='text-body text-foreground'>동기화 대기: {stats.pending}개</Text>
              <Text className='text-body text-foreground'>동기화 실패: {stats.failed}개</Text>
              <Text className='text-body text-foreground'>진행 중: {stats.inProgress}개</Text>
            </>
          )}
        </View>
      </View>

      {/* Quick Actions */}
      <View className='gap-sm'>
        <Pressable
          variant='outline'
          className='flex-row items-center justify-center gap-xs py-3 rounded-lg border border-card-border'
          onPress={onRefresh}
        >
          <RefreshCw size={16} color='#228B22' />
          <Text className='text-body text-primary'>새로고침</Text>
        </Pressable>

        <Pressable
          variant='outline'
          className='flex-row items-center justify-center gap-xs py-3 rounded-lg border border-primary bg-primary/5'
          onPress={onManualSync}
        >
          <Upload size={16} color='#228B22' />
          <Text className='text-body text-primary font-semibold'>전체 동기화 (Push + Pull)</Text>
        </Pressable>
      </View>
    </View>
  );
}
import React, { useState } from 'react';
import { View, ScrollView, RefreshControl, Alert } from 'react-native';
import { MobileHeader, Container, Stack } from '@/shared/components';
import { ArrowLeft } from 'lucide-react-native';
import { router } from 'expo-router';
import MapboxGL from '@rnmapbox/maps';
import { db, trips, schedules, expenses, syncQueue, offlineCities, tripActivations } from '@/shared/db';
import type { Trip, Schedule, Expense, SyncQueueItem, OfflineCity, TripActivation } from '@/shared/db/schema';
import { resetDatabase } from '@/shared/db';
import { getSyncQueueStats } from '@/shared/services/sync/queue';
import { triggerSync } from '@/shared/services/sync/engine';
import { DashboardView } from './DashboardView';
import { DataInspectorView } from './DataInspectorView';
import { ToolsView } from './ToolsView';
import { Pressable } from '@repo/ui';
import { Text } from 'react-native';

type ViewMode = 'dashboard' | 'inspector' | 'tools';

export default function DebugScreen() {
  const [refreshing, setRefreshing] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('dashboard');

  // Data States
  const [tripsData, setTripsData] = useState<Trip[]>([]);
  const [schedulesData, setSchedulesData] = useState<Schedule[]>([]);
  const [expensesData, setExpensesData] = useState<Expense[]>([]);
  const [offlineCitiesData, setOfflineCitiesData] = useState<OfflineCity[]>([]);
  const [syncQueueData, setSyncQueueData] = useState<SyncQueueItem[]>([]);
  const [tripActivationsData, setTripActivationsData] = useState<TripActivation[]>([]);
  const [stats, setStats] = useState<{ pending: number; inProgress: number; failed: number; total: number } | null>(
    null,
  );

  const loadData = async () => {
    try {
      setRefreshing(true);

      const tripsResult = await db.select().from(trips).all();
      setTripsData(tripsResult);

      const schedulesResult = await db.select().from(schedules).all();
      setSchedulesData(schedulesResult);

      const expensesResult = await db.select().from(expenses).all();
      setExpensesData(expensesResult);

      const offlineCitiesResult = await db.select().from(offlineCities).all();
      setOfflineCitiesData(offlineCitiesResult);

      const syncQueueResult = await db.select().from(syncQueue).all();
      setSyncQueueData(syncQueueResult);

      const tripActivationsResult = await db.select().from(tripActivations).all();
      setTripActivationsData(tripActivationsResult);

      const statsResult = await getSyncQueueStats();
      setStats(statsResult);

      console.log('✅ Debug data loaded');
    } catch (error) {
      console.error('❌ Failed to load debug data:', error);
      Alert.alert('오류', '데이터를 불러올 수 없습니다.');
    } finally {
      setRefreshing(false);
    }
  };

  const handleResetDatabase = () => {
    Alert.alert('⚠️ DB 초기화', '모든 로컬 데이터가 삭제됩니다.\n계속하시겠습니까?', [
      { text: '취소', style: 'cancel' },
      {
        text: '초기화',
        style: 'destructive',
        onPress: async () => {
          try {
            await resetDatabase();
            await loadData();
            Alert.alert('✅ 성공', 'DB가 초기화되었습니다.');
          } catch (error) {
            console.error('❌ Failed to reset DB:', error);
            Alert.alert('❌ 실패', 'DB 초기화에 실패했습니다.');
          }
        },
      },
    ]);
  };

  const handleClearOfflineMaps = () => {
    Alert.alert(
      '⚠️ 오프라인 지도 완전 삭제',
      'Mapbox 네이티브 오프라인 팩과 DB의 offlineCities 레코드를 모두 삭제합니다.\n계속하시겠습니까?',
      [
        { text: '취소', style: 'cancel' },
        {
          text: '삭제',
          style: 'destructive',
          onPress: async () => {
            try {
              // 1. Mapbox 네이티브 오프라인 팩 삭제
              const packs = await MapboxGL.offlineManager.getPacks();
              console.log(`🗑️ Deleting ${packs.length} offline packs...`);

              for (const pack of packs) {
                await MapboxGL.offlineManager.deletePack(pack.name);
                console.log(`✅ Deleted pack: ${pack.name}`);
              }

              // 2. DB의 offlineCities 테이블 비우기
              await db.delete(offlineCities);
              console.log('✅ Cleared offlineCities table');

              await loadData();
              Alert.alert('✅ 성공', `${packs.length}개의 오프라인 지도와 DB 레코드를 모두 삭제했습니다.`);
            } catch (error) {
              console.error('❌ Failed to clear offline maps:', error);
              Alert.alert('❌ 실패', '오프라인 지도 삭제에 실패했습니다.');
            }
          },
        },
      ],
    );
  };

  const handleManualSync = async () => {
    try {
      const result = await triggerSync();

      if (result.success) {
        await loadData(); // 데이터 새로고침
        Alert.alert('✅ 성공', result.message);
      } else {
        Alert.alert('❌ 실패', result.message);
      }
    } catch (error) {
      console.error('❌ Manual sync error:', error);
      Alert.alert('❌ 오류', '동기화 중 오류가 발생했습니다.');
    }
  };

  const handleManualActivate = async (tripId: string, tripName: string) => {
    Alert.alert('🟢 수동 활성화', `"${tripName}" 여행을 활성화하시겠습니까?`, [
      { text: '취소', style: 'cancel' },
      {
        text: '활성화',
        },
      ],
    );
  };

  React.useEffect(() => {
    loadData();
  }, []);

  return (
    <View className='flex-1 bg-background'>
      <MobileHeader
        title='디버그 콘솔'
        leftIcon={<ArrowLeft size={20} color='#1F1F1F' />}
        onLeftPress={() => router.back()}
      />

      <View className='px-md py-sm bg-background'>
        <View className='flex-row p-1 bg-muted rounded-lg'>
          {(['dashboard', 'inspector', 'tools'] as const).map((mode) => (
            <Pressable
              key={mode}
              variant='ghost'
              className={`flex-1 py-xs items-center rounded-md ${
                viewMode === mode ? 'bg-background shadow-sm' : 'bg-transparent'
              }`}
              onPress={() => setViewMode(mode)}
            >
              <Text
                className={`text-label font-semibold ${
                  viewMode === mode ? 'text-foreground' : 'text-muted-foreground'
                }`}
              >
                {mode === 'dashboard' ? '대시보드' : mode === 'inspector' ? '데이터' : '도구'}
              </Text>
            </Pressable>
          ))}
        </View>
      </View>

      <ScrollView className='flex-1' refreshControl={<RefreshControl refreshing={refreshing} onRefresh={loadData} />}>
        <Container>
          <Stack direction='vertical' gap='md' className='py-sm'>
            {viewMode === 'dashboard' && (
              <DashboardView
                stats={stats}
                counts={{
                  trips: tripsData.length,
                  schedules: schedulesData.length,
                  expenses: expensesData.length,
                  activations: tripActivationsData.filter((a) => a.isActivated).length,
                  offlineCities: offlineCitiesData.length,
                }}
                onRefresh={loadData}
                onManualSync={handleManualSync}
              />
            )}
            {viewMode === 'inspector' && (
              <DataInspectorView
                data={{
                  trips: tripsData,
                  schedules: schedulesData,
                  expenses: expensesData,
                  activations: tripActivationsData,
                  offlineCities: offlineCitiesData,
                  syncQueue: syncQueueData,
                }}
                onActivateTrip={handleManualActivate}
                onDeactivateTrip={handleManualDeactivate}
              />
            )}
            {viewMode === 'tools' && (
              <ToolsView
                onResetDatabase={handleResetDatabase}
                onClearOfflineMaps={handleClearOfflineMaps}
                onClearActivations={handleClearAllActivations}
              />
            )}
