  const React = require('react');
  const { Pressable, Text } = require('react-native');
  return { Pressable: ({ children, ...props }: { children: React.ReactNode }) => <Pressable {...props}>{typeof children === 'string' ? <Text>{children}</Text> : children}</Pressable> };
});
jest.mock('lucide-react-native', () => ({ ArrowLeft: () => null, Database: () => null, Wifi: () => null, WifiOff: () => null, RotateCcw: () => null, RefreshCw: () => null, Upload: () => null }));
jest.mock('expo-router', () => ({ router: { back: jest.fn() } }));
jest.mock('@rnmapbox/maps', () => ({ __esModule: true, default: {} }));
jest.mock('@/features/debug/ui/DataInspectorView', () => ({ DataInspectorView: () => null }));
jest.mock('@/features/debug/ui/ToolsView', () => ({ ToolsView: () => null }));

const syncMock = jest.mocked(syncData);
const selectMock = jest.mocked(db.select);

beforeEach(() => {
  useNetworkStore.setState({ realStatus: 'unknown', overrideStatus: null });
  useAuthStore.setState({ isInitialized: true, isAuthenticated: true });
  syncMock.mockResolvedValue(undefined);
  jest.spyOn(Alert, 'alert').mockImplementation(() => undefined);
  jest.spyOn(console, 'log').mockImplementation(() => undefined);
});
afterEach(() => { jest.restoreAllMocks(); });

async function openDebug() {
  const screen = render(<SyncProvider isDatabaseReady={true}><DebugScreen /></SyncProvider>);
  await act(async () => {});
  return screen;
}

