  return (
    <View className='flex-1 bg-background'>
      {/* Header */}
      <MobileHeader
        title='일정 상세'
        leftIcon={<ChevronLeft size={24} color='hsl(0, 0%, 12%)' strokeWidth={2} />}
        onLeftPress={onBack}
      />

      <ScrollView className='flex-1'>
        <Container>
          <Stack direction='vertical' gap='md' className='py-sm'>
